use std::{fs,io::{self,Read}};
use zeroize::Zeroizing;
pub(super) struct ProfileInput{bytes:Zeroizing<Vec<u8>>}
impl ProfileInput{pub(super) fn as_bytes(&self)->&[u8]{&self.bytes}}
// Exact old file-read/wrap boundary. Later encoded_len admission is excluded.
pub(super) fn read_file(path:&str)->io::Result<ProfileInput>{
 let bytes=Zeroizing::new(fs::read(path)?);Ok(ProfileInput{bytes})
}
// Byte adapter of the old fs::read ? -> Zeroizing boundary for fault readers.
// Unlike File, this generic reader supplies no metadata capacity hint.
pub(super) fn read_profile(mut reader:impl Read)->io::Result<ProfileInput>{
 let mut bytes=Vec::new();reader.read_to_end(&mut bytes)?;
 Ok(ProfileInput{bytes:Zeroizing::new(bytes)})
}

