use std::{fs,io::{self,Read},path::PathBuf,os::unix::fs::{DirBuilderExt,symlink}};
#[path="src/profile_input.rs"]mod profile_input;
mod support;
use support::observe;
struct Directory(PathBuf);
impl Drop for Directory{fn drop(&mut self){fs::remove_dir_all(&self.0).unwrap();}}
fn directory(label:&str)->Directory{let path=std::env::temp_dir().join(format!("charlotte-baseline-profile-{}-{label}",std::process::id()));fs::DirBuilder::new().mode(0o700).create(&path).unwrap();Directory(path)}
struct PartialError(bool);
impl Read for PartialError{fn read(&mut self,out:&mut[u8])->io::Result<usize>{if self.0{return Err(io::ErrorKind::Other.into())}self.0=true;out[..8].fill(b'Z');Ok(8)}}
#[test]
fn partial_error_erases_prefix(){let observed=observe(0,0,0,||assert!(profile_input::read_profile(PartialError(false)).is_err()));assert!(observed.copy_erased,"partial prefix retained: {observed:?}");}
#[test]
fn read_stage_rejects_oversize(){let d=directory("large");let p=d.0.join("profile");fs::write(&p,vec![b'Z';65537]).unwrap();assert!(profile_input::read_file(p.to_str().unwrap()).is_err());}
#[test]
fn read_stage_rejects_empty(){let d=directory("empty");let p=d.0.join("profile");fs::write(&p,b"").unwrap();assert!(profile_input::read_file(p.to_str().unwrap()).is_err());}
#[test]
fn read_stage_rejects_symlink(){let d=directory("alias");let p=d.0.join("profile");let alias=d.0.join("alias");fs::write(&p,b"ZZZZZZZZ").unwrap();symlink(&p,&alias).unwrap();assert!(profile_input::read_file(alias.to_str().unwrap()).is_err());}
#[test]
fn existing_successful_owner_erases(){let observed=observe(0,0,0,||{let p=profile_input::read_profile(io::Cursor::new(b"ZZZZZZZZ")).unwrap();assert_eq!(p.as_bytes(),b"ZZZZZZZZ");drop(p);});assert!(observed.copy_erased,"successful input retained: {observed:?}");assert_eq!(observed.copy_releases,1);}

